after:
import * as Effect from "effect/Effect";
export class HranaError extends Data.TaggedError("Turso::HranaError")<{ readonly message: string; readonly code?: string }> {}
type Result = { readonly type: "ok" } | { readonly type: "error"; readonly error: { readonly message: string; readonly code?: string } };
declare const pipeline: (sql: string) => ReadonlyArray<Result>!HranaError;
export const transaction = effect (statements: ReadonlyArray<string>): void!HranaError => {
  if (statements.length === 0) return;
  const [result] = try pipeline(["BEGIN", ...statements, "COMMIT"].join(";\n"));
  if (result === undefined) {
    throw new HranaError({ message: "Turso returned no result" });
  }
  if (result.type === "error") {
    throw new HranaError({ message: result.error.message, code: result.error.code });
  }
};
